using System;using System.IO;using Foundation;using UIKit;
namespace ReuseSmokeIOS;
public static class Program {public static void Main(string[] args){Console.WriteLine("Managed Main reached");UIApplication.Main(args,null,typeof(AppDelegate));}}
[Register("AppDelegate")] public class AppDelegate:UIApplicationDelegate {public override bool FinishedLaunching(UIApplication app,NSDictionary options){var path=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),"reuse-result.txt");Console.WriteLine("Result path="+path);try {File.WriteAllText(path+".started","Managed FinishedLaunching reached");Console.WriteLine("Starting recovered checks");var result=ReuseSmoke.Checks.Run();File.WriteAllText(path,result);Console.WriteLine(result);}catch(Exception e){File.WriteAllText(path,"FAIL "+e);Console.WriteLine(e);}return true;}}